import numpy as np

def expand_9s_to_2x2(grid):
    output = grid.copy()
    h, w = grid.shape
    visited = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if grid[r, c] == 9 and not visited[r, c]:
                # Expand to 2x2
                for dr in [0, 1]:
                    for dc in [0, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            output[nr, nc] = 9
                            visited[nr, nc] = True
    return output

